package com.muxigame.city;
import java.util.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder(CityMod.ID) @PrefixGameTestTemplate(false)
public class CityTestsRuralCooking {
 @GameTest(template="empty") public static void earnedCookingPreventsDuplicatePreparedMealPurchase(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var cook=f.r.state.people.values().stream().filter(p->p.role==RuralRules.Role.COOK).findFirst().orElseThrow();var family=f.r.state.families.get(cook.family);var stocks=f.r.stocks(family.id);for(var stock:stocks){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}RuralRules.put(stocks,false,10);cook.workingTicks=(long)Math.ceil(2*36000/HouseholdCooking.RURAL_COOK_RATE);cook.cookingCredit=0;h.assertTrue(RuralCooking.breadWanted(f.r,f.village,family,stocks)==2,"Two portions of earned cooking leave only two prepared portions to buy");cook.workingTicks=(long)Math.ceil(4*36000/HouseholdCooking.RURAL_COOK_RATE);h.assertTrue(RuralCooking.breadWanted(f.r,f.village,family,stocks)==0&&cook.cookingCredit==0&&RuralRules.count(stocks,false)==10,"Forecast cannot spend time twice or create actual cooked food");cook.workingTicks=0;h.assertTrue(RuralCooking.breadWanted(f.r,f.village,family,stocks)==4,"Having raw wheat alone does not promise unearned future work");}h.succeed();}
 @GameTest(template="empty") public static void headKeepsEdibleMealsEvenWhenRawWarehouseIsFull(GameTestHelper h){try(var f=new CityTestsScale.Fixture(h)){CityTestsModel.configure(f);var head=f.t.head(f.village.id);var p=f.r.state.people.get(head.worker);var stocks=f.r.stocks(p.family);for(var stock:stocks){stock.wheat=stock.bread=0;RuralMeat.clear(stock);}RuralRules.put(stocks,false,740);RuralRules.put(stocks,true,10);h.assertTrue(RuralCooking.available(f.r,p,1,stocks)==2,"Only surplus above the head family's two ready meals can be sold");RuralRules.take(stocks,true,8);RuralRules.put(stocks,false,8);h.assertTrue(RuralCooking.available(f.r,p,1,stocks)==0,"748 raw wheat is not a substitute for preserving the last ready meal");p.nourishment=12;h.assertTrue(RuralCooking.householdReserve(f.r,f.r.state.families.get(p.family))>8,"Existing calorie debt enters the private reserve calculation");}h.succeed();}
}
